function parseNumber(value) {
  let s = String(value).trim().replace(/[\s\u00a0]/g, "");
  if (!s) return null;
  if (s.includes(",")) s = s.replaceAll(".", "").replace(",", ".");
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replaceAll(".", "");
  if (!/^-?\d+(\.\d+)?$/.test(s)) return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}
